808: bool ClipboardPromise::RejectIfDocumentNotFocused() {
809:   DCHECK_CALLED_ON_VALID_SEQUENCE(sequence_checker_);
810:   auto* window = To<LocalDOMWindow>(GetExecutionContext());
811: 
812:   // Trusted surfaces (WebUI, DevTools, chrome-untrusted, and Isolated Web Apps)
813:   // are exempt from the focus requirement. See the corresponding browser-side
814:   // check in ContentBrowserClient::IsClipboardPasteAllowed().
815:   // Prerendering documents are excluded because WebPreferences (which carries
816:   // clipboard_focus_exempt from the primary main frame) is shared with the
817:   // prerendering page, and prerendering documents must not bind ClipboardHost.
818:   LocalFrame* frame = window->GetFrame();
819:   const bool clipboard_focus_exempt =
820:       frame && frame->GetSettings()->GetClipboardFocusExempt();
821:   if (!window->document()->IsPrerendering() &&
822:       (clipboard_focus_exempt || window->document()->hasFocus())) {
823:     return false;
824:   }
825:   script_promise_resolver_->RejectWithDOMException(
826:       DOMExceptionCode::kNotAllowedError, "Document is not focused.");
827:   return true;
828: }
